{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "While it is now apparent clinical sequelae (long COVID) may persist after acute COVID-19, their nature, frequency and aetiology are poorly characterised.",
      "reason": "The text explicitly describes the current state of knowledge regarding long COVID, noting that while it is known to persist, its nature, frequency, and aetiology are poorly understood."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This study aims to regularly synthesise evidence on long COVID characteristics, to help inform clinical management, rehabilitation strategies and interventional studies to improve long-­ term outcomes.",
      "reason": "The authors explain the importance and need for the review, which is to synthesize evidence to inform clinical management and future research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Systematic reviews conducted early during the COVID-­ 19 pandemic soon became redundant due to the rapidity with which new research was released. In recognition of this, many reviewers have moved towards the concept of a 'living systematic review' (LSR)... We conducted a 'living' systematic review to provide frequently updated evidence on the symptoms and complications of long COVID.",
      "reason": "The authors acknowledge that previous systematic reviews became redundant due to the speed of new research and explain the need for a 'living' systematic review approach to provide updated evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of characteristics/symptoms of long COVID, not a review of intervention effects."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
